class Box { public int N; }
model Identity { int N; }
record Name(string Text);
record Envelope {
 private int code;
 public Name Name { get; init; }
 public Box Box { get; init; }
 public Identity Id { get; init; }
 public int Computed { get { Print("unexpected getter"); return code; } }
 public Envelope(Name name, Box box, Identity id, int value) { Name = name; Box = box; Id = id; code = value; }
}
void Main() {
 var box = new Box { N = 2 }; var id = new Identity { N = 3 };
 var a = new Envelope(new Name("A" + "da"), box, id, 1);
 var b = new Envelope(new Name("Ada"), box, id, 1);
 Print(a == b); Print(a.Equals(b)); Print(a.GetHashCode() == b.GetHashCode());
 Print(a == new Envelope(new Name("Ada"), box, id, 2));
 Print(a == new Envelope(new Name("Ada"), new Box { N = 2 }, id, 1));
 Print(a == new Envelope(new Name("Ada"), box, new Identity { N = 3 }, 1));
 var copied = a with {}; Print(copied == a); box.N++; Print(copied.Box.N);
}
